//! Source generator of the straight line routines (`native_*.rs`, test builds only).
//!
//! The compiled [`Program`] of a routine has only a few hundred static ops (the loops repeat
//! bodies). Each op becomes one `m.run_item(&[..])` call with a literal row: after inlining, the
//! dispatch, the operand decoding and the bounds checks of the interpreter fold away, and a loop
//! is a Rust `for`. Forward jumps become labeled blocks. The generated files are checked in; the
//! tests below fail when one is stale (`NS4_REGEN=1 cargo test -p nord-core native_gen` rewrites
//! them) and compare their output with the interpreter state for state.

use super::compile::{ctl, Program};
use super::{Machine, Row};

impl Machine {
    /// Panics unless `other` holds the same registers, flags and DM (`call` names the failure).
    pub(in crate::organ) fn assert_same_state(&self, other: &Machine, call: usize) {
        assert_eq!(self.d, other.d, "d, call {call}");
        let idx = |m: &Machine| (m.i, m.m, m.l, m.b);
        assert_eq!(idx(self), idx(other), "index, call {call}");
        let fl = |m: &Machine| (m.mr, m.an, m.az, m.lcntr);
        assert_eq!(fl(self), fl(other), "flags, call {call}");
        assert!(self.mem == other.mem, "DM, call {call}");
    }
}

/// Rust source of `fn <name>(m: &mut Machine)` running `prog`.
pub(super) fn source(name: &str, what: &str, prog: &Program) -> String {
    let mut out = format!(
        "//! Straight line `{what}`, GENERATED by `native_gen.rs`; do not edit.\n\
         //! Regenerate: `NS4_REGEN=1 cargo test -p nord-core native_gen`. Bit exact with the\n\
         //! interpreter (`native_gen::tests` compares the machine state).\n\n\
         use super::Machine;\n\n\
         #[rustfmt::skip]\n#[allow(clippy::all)]\n\
         pub(super) fn {name}(m: &mut Machine) {{\n"
    );
    assert!(
        prog.ops.iter().all(|o| o[0] != ctl::REF),
        "a reference path instruction cannot be generated"
    );
    region(prog, 0, prog.ops.len(), 1, &mut out);
    out.push_str("}\n");
    out
}

fn row_lit(r: &Row) -> String {
    let v: Vec<String> = r.iter().map(i32::to_string).collect();
    format!("[{}]", v.join(", "))
}

/// Emits the ops `lo..hi` (one loop body or the routine) with labeled blocks for its jumps.
fn region(prog: &Program, lo: usize, hi: usize, depth: usize, out: &mut String) {
    let pad = "    ".repeat(depth);
    // (jump op, target) of the forward jumps of this region; a block that ends at the target
    // starts at the first jump that can reach any target up to its own, so blocks nest
    let jumps: Vec<(usize, usize)> = scan(prog, lo, hi)
        .into_iter()
        .filter(|&(_, t)| t > lo)
        .collect();
    let start_of = |t: usize| {
        jumps
            .iter()
            .filter(|j| j.1 <= t)
            .map(|j| j.0)
            .min()
            .unwrap()
    };
    let mut targets: Vec<usize> = jumps.iter().map(|j| j.1).collect();
    targets.sort_unstable();
    targets.dedup();
    let mut p = lo;
    let mut open: Vec<usize> = Vec::new();
    while p <= hi {
        while open.last() == Some(&p) {
            open.pop();
            out.push_str(&format!("{pad}}}\n"));
        }
        let mut starting: Vec<usize> = targets
            .iter()
            .copied()
            .filter(|&t| start_of(t) == p)
            .collect();
        starting.sort_unstable_by(|a, b| b.cmp(a));
        for t in starting {
            open.push(t);
            out.push_str(&format!("{pad}'l{t}: {{\n"));
        }
        if p == hi {
            break;
        }
        let row = &prog.ops[p];
        p += 1;
        match row[0] {
            ctl::JUMP => {
                let cond = match row[1] {
                    1 => "true",
                    2 => "!m.az[0]",
                    _ => "m.az[0]",
                };
                out.push_str(&format!("{pad}if {cond} {{ break 'l{}; }}\n", row[2]));
            }
            ctl::LOOP => {
                let body = row[2] as usize;
                out.push_str(&format!("{pad}for _ in 0..{} {{\n", row[1]));
                region(prog, p, p + body, depth + 1, out);
                out.push_str(&format!("{pad}}}\n{pad}m.lcntr = 0;\n"));
                p += body;
            }
            _ => out.push_str(&format!("{pad}m.run_item(&{});\n", row_lit(row))),
        }
    }
    assert!(open.is_empty(), "unclosed block");
}

/// The jumps of `lo..hi` outside nested loops: `(op, target)`.
fn scan(prog: &Program, lo: usize, hi: usize) -> Vec<(usize, usize)> {
    let mut v = Vec::new();
    let mut p = lo;
    while p < hi {
        let row = &prog.ops[p];
        p += 1;
        match row[0] {
            ctl::JUMP => {
                assert!(row[2] as usize > p - 1, "backward jump");
                v.push((p - 1, row[2] as usize));
            }
            ctl::LOOP => p += row[2] as usize,
            _ => {}
        }
    }
    v
}

#[cfg(test)]
mod tests {
    use super::super::compile::compile;
    use super::super::{Machine, GEN_ROWS, PROC_ROWS};
    use super::*;

    #[test]
    fn jumps_become_nested_labeled_blocks_and_loops_become_for() {
        let ops = vec![
            [ctl::LOOP, 3, 4, 0, 0, 0, 0, 0],
            [ctl::JUMP, 2, 3, 0, 0, 0, 0, 0],
            [7, 1, 5, 0, 0, 0, 0, 0],
            [ctl::JUMP, 1, 5, 0, 0, 0, 0, 0],
            [7, 2, 6, 0, 0, 0, 0, 0],
            [7, 3, 7, 0, 0, 0, 0, 0],
        ];
        // loop body ops 1..5: jump to 3 (skips op 2), jump to 5 (the end of the body)
        let prog = Program {
            ops,
            refs: Vec::new(),
        };
        let s = source("f", "test", &prog);
        assert!(s.contains("for _ in 0..3 {"));
        assert!(s.contains("'l5: {") && s.contains("'l3: {"));
        assert!(s.contains("if !m.az[0] { break 'l3; }"));
        assert!(s.contains("m.run_item(&[7, 2, 6, 0, 0, 0, 0, 0]);"));
    }

    /// Checks (or with `NS4_REGEN=1` rewrites) the generated file `file`.
    fn check(file: &str, name: &str, what: &str, rows: &[Row]) {
        let want = source(name, what, &compile(rows));
        let path = format!("{}/src/organ/b3_bass_fw/{file}", env!("CARGO_MANIFEST_DIR"));
        if std::env::var_os("NS4_REGEN").is_some() {
            std::fs::write(&path, &want).unwrap();
        }
        let have = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            have.replace("\r\n", "\n") == want,
            "{file} is stale: NS4_REGEN=1 cargo test -p nord-core native_gen"
        );
    }

    #[test]
    fn the_generated_routines_are_up_to_date() {
        check(
            "native_bass_gen.rs",
            "gen_call",
            "B3 Bass generator 0x121BBE",
            &GEN_ROWS,
        );
        check(
            "native_bass_proc.rs",
            "proc_call",
            "B3 Bass processor 0x122296",
            &PROC_ROWS,
        );
    }

    fn chord_machine(native: bool) -> Machine {
        let mut m = Machine::new();
        m.load_image(include_str!(
            "../../../../../docs/research/data/bass-fw-image.csv"
        ));
        m.load_image(include_str!(
            "../../../../../docs/research/data/bass-fw-chord-delta.csv"
        ));
        m.set_programs(Some(&GEN_ROWS), &PROC_ROWS);
        if native {
            m.use_native_bass();
        }
        m
    }

    #[test]
    fn the_native_bass_routines_equal_the_interpreter_state_for_state() {
        let (mut a, mut b) = (chord_machine(false), chord_machine(true));
        for call in 0..600 {
            assert_eq!(a.step(), b.step(), "output, call {call}");
            a.assert_same_state(&b, call);
        }
    }
}
